ctx.api.middleware.register({
  name: 'reading-time',
  operations: ['card.render'],
  handler: async function(mw, next) {
    await next();
    var card = mw.args && mw.args[0];
    var cardEl = mw.args && mw.args[1];
    if (!card || !cardEl || !card.body) return;
    if (cardEl.querySelector('.plugin-reading-time')) return;
    var words = String(card.body).split(/\s+/).filter(Boolean).length;
    if (words < 30) return;
    var minutes = Math.max(1, Math.round(words / 200));
    var badge = document.createElement('span');
    badge.className = 'plugin-reading-time';
    badge.textContent = minutes + ' min read';
    var content = cardEl.querySelector('.card-content') || cardEl;
    content.appendChild(badge);
  }
});
ctx.logger.info('Reading time estimates active');

teardownJs:
// Badges were created outside the tracked-resource APIs, so remove
// the ones still in the document ourselves.
var badges = document.querySelectorAll('.plugin-reading-time');
for (var i = 0; i < badges.length; i++) {
  if (badges[i].parentNode) badges[i].parentNode.removeChild(badges[i]);
}
